head.b:skin:
/* 
THEME: Medical Compendium (Clinical Teal & Slate)
SYSTEM: Academic Health & Psychology Summary
*/
:root {
    --teal: #0d9488;
    --slate-dark: #1e293b;
    --clinical-blue: #f0f9ff;
    --accent-red: #ef4444;
    --text-main: #334155;
}
body {
    background-color: #f8fafc;
    color: var(--text-main);
    font-family: 'Inter', 'Segoe UI', sans-serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: linear-gradient(135deg, var(--slate-dark), #0f172a);
    color: #fff;
    padding: 50px 20px;
    text-align: center;
    border-bottom: 4px solid var(--teal);
}
.header-wrap h1 { color: var(--teal); margin: 0; font-size: 28px; letter-spacing: 1px; }
.main-container {
    max-width: 900px;
    margin: -30px auto 60px;
    padding: 20px;
}
.medical-card {
    background: #ffffff;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.08);
    padding: 35px;
    margin-bottom: 25px;
    border-left: 6px solid var(--teal);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: 700;
    margin-bottom: 8px;
    color: var(--slate-dark);
    font-size: 13px;
    text-transform: uppercase;
}
.input-group input, .input-group textarea {
    width: 100%;
    padding: 14px;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fdfdfd;
}
.input-group textarea { height: 120px; font-size: 14px; }

.lang-options { display: flex; gap: 25px; margin-top: 10px; }
.lang-item { display: flex; align-items: center; cursor: pointer; font-weight: 600; font-size: 14px; }
.lang-item input { width: auto; margin-right: 8px; accent-color: var(--teal); }

h2 { color: var(--slate-dark); font-size: 22px; margin-top: 0; display: flex; align-items: center; }
h2::before { content: '📋'; margin-right: 10px; }

.copy-btn {
    background: var(--teal);
    color: white;
    border: none;
    padding: 18px;
    cursor: pointer;
    font-weight: bold;
    width: 100%;
    border-radius: 8px;
    transition: 0.3s;
    font-size: 15px;
    text-transform: uppercase;
}
.copy-btn:hover { background: var(--slate-dark); box-shadow: 0 4px 12px rgba(13, 148, 136, 0.3); }
footer { text-align: center; color: #94a3b8; padding: 25px; font-size: 12px; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "[Topik Belum Diisi]";
    var notes = document.getElementById("inputNotes").value || "[Gunakan pengetahuan medismu untuk merangkum topik ini]";

    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("🔬 Prompt Akademik (" + (selectedLang === 'id' ? 'Indonesia' : 'English') + ") Berhasil Disalin!");
}
